<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Lotte World Tower</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
            background-color: #f0f0f0;
        }
        #container {
            width: 100%;
            height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }
        #panels {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
        }
        .panel {
            width: 200px;
            height: 200px;
            margin: 10px;
            background-color: #fff;
            border: 1px solid #ddd;
            padding: 10px;
            font-size: 19px;
        }
        #three-container {
            width: 600px;
            height: 400px;
            border: 1px solid #ddd;
            margin: 20px;
        }
        #controls {
            margin: 20px;
        }
        button {
            font-size: 19px;
            padding: 10px;
            margin: 10px;
        }
        #model-name {
            position: absolute;
            top: 10px;
            left: 10px;
            font-size: 24px;
        }
    </style>
</head>
<body>
    <div id="model-name">llama-3.3-70b</div>
    <div id="container">
        <div id="panels">
            <div class="panel" id="site-plan">
                <svg width="180" height="180">
                    <rect x="10" y="10" width="160" height="160" fill="#ccc" />
                    <text x="50" y="50" font-size="24">Site Plan</text>
                </svg>
            </div>
            <div class="panel" id="floor-plan">
                <svg width="180" height="180">
                    <rect x="10" y="10" width="160" height="160" fill="#ccc" />
                    <text x="50" y="50" font-size="24">Floor Plan</text>
                </svg>
            </div>
            <div class="panel" id="elevation">
                <svg width="180" height="180">
                    <rect x="10" y="10" width="160" height="160" fill="#ccc" />
                    <text x="50" y="50" font-size="24">Elevation</text>
                </svg>
            </div>
            <div class="panel" id="section">
                <svg width="180" height="180">
                    <rect x="10" y="10" width="160" height="160" fill="#ccc" />
                    <text x="50" y="50" font-size="24">Section</text>
                </svg>
            </div>
        </div>
        <div id="three-container"></div>
        <div id="controls">
            <button id="rotate">Rotate</button>
            <button id="zoom">Zoom</button>
            <button id="reset">Reset</button>
        </div>
    </div>
    <script src="../runtime/three-runtime.js"></script>
    <script>
        let scene = new THREE.Scene();
        let camera = new THREE.PerspectiveCamera(75, 600 / 400, 0.1, 1000);
        let renderer = new THREE.WebGLRenderer({
            canvas: document.createElement('canvas'),
            antialias: true
        });
        renderer.setSize(600, 400);
        document.getElementById('three-container').appendChild(renderer.domElement);
        let towerGeometry = new THREE.BoxGeometry(100, 555, 100);
        let towerMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
        let tower = new THREE.Mesh(towerGeometry, towerMaterial);
        scene.add(tower);
        camera.position.z = 500;
        let orbitControls = new THREE.OrbitControls(camera, renderer.domElement);
        function animate() {
            requestAnimationFrame(animate);
            renderer.render(scene, camera);
        }
        animate();
        document.getElementById('rotate').addEventListener('click', () => {
            tower.rotation.x += 0.1;
            tower.rotation.y += 0.1;
        });
        document.getElementById('zoom').addEventListener('click', () => {
            camera.position.z -= 50;
        });
        document.getElementById('reset').addEventListener('click', () => {
            camera.position.z = 500;
            tower.rotation.x = 0;
            tower.rotation.y = 0;
        });
        document.addEventListener('keydown', (event) => {
            if (event.key === ' ') {
                tower.rotation.x += 0.1;
                tower.rotation.y += 0.1;
            } else if (event.key === '+') {
                camera.position.z -= 50;
            } else if (event.key === '-') {
                camera.position.z += 50;
            } else if (event.key === 'r') {
                camera.position.z = 500;
                tower.rotation.x = 0;
                tower.rotation.y = 0;
            }
        });
    </script>
</body>
</html>
